# Generated by Gemini 3.6 Flash

import ijson
import math
import csv
from collections import defaultdict

# ==========================================
# CONFIGURATION
# ==========================================
INPUT_JSON_PATH = "fire_archive_SV-C2_820768.json"
OUTPUT_CSV_PATH = "australia_bushfires_hexbin_yearly.csv"

# HEXAGON SIZE CONTROL:
# Controls side length / radius in degrees.
# - 0.25 deg (~25-30 km) -> High detail, small file (~10-20 MB)
# - 0.50 deg (~50 km)    -> Medium detail, very light file (~3-5 MB)
# - 1.00 deg (~100 km)   -> Macro overview, tiny file (<1 MB)
HEX_SIZE_DEG = 0.5

# ==========================================
# HEXAGON MATH (Axial Grid Conversion)
# ==========================================
# Flat-topped hexagon projection math in lat/lon space
SQRT_3 = math.sqrt(3)


def latlon_to_hex(lat, lon, size):
    """
    Converts latitude/longitude into a discrete hexagonal grid coordinate (q, r)
    and computes the center (lat, lon) of that hexagon cell.
    """
    # Approximate spherical correction for latitude stretching
    x = lon * math.cos(math.radians(lat))
    y = lat

    # Convert projected x, y into axial hexagon coordinates
    q = (SQRT_3 / 3 * x - 1 / 3 * y) / size
    r = (2 / 3 * y) / size

    # Cube rounding
    cube_x = q
    cube_z = r
    cube_y = -cube_x - cube_z

    rx = round(cube_x)
    ry = round(cube_y)
    rz = round(cube_z)

    x_diff = abs(rx - cube_x)
    y_diff = abs(ry - cube_y)
    z_diff = abs(rz - cube_z)

    if x_diff > y_diff and x_diff > z_diff:
        rx = -ry - rz
    elif y_diff > z_diff:
        ry = -rx - rz
    else:
        rz = -rx - ry

    hex_q, hex_r = int(rx), int(rz)

    # Calculate exact center lat/lon of the binned hexagon
    center_y = (3 / 2 * hex_r) * size
    center_x = (SQRT_3 * hex_q + SQRT_3 / 2 * hex_r) * size

    center_lat = center_y
    center_lon = center_x / math.cos(math.radians(center_lat)) if math.cos(math.radians(center_lat)) != 0 else center_x

    return hex_q, hex_r, round(center_lat, 4), round(center_lon, 4)


def process_large_json():
    print(f"Streaming and binning '{INPUT_JSON_PATH}' with HEX_SIZE_DEG = {HEX_SIZE_DEG}...")

    # Aggregation key: (year, hex_q, hex_r) -> [count, sum_frp, center_lat, center_lon]
    hex_data = defaultdict(lambda: [0, 0.0, 0.0, 0.0])

    # Stream JSON item by item to prevent memory overhead
    with open(INPUT_JSON_PATH, "r", encoding="utf-8") as f:
        # ijson parse streams individual items from the root array
        for item in ijson.items(f, "item"):
            lat = item.get("latitude")
            lon = item.get("longitude")
            acq_date = item.get("acq_date", "")
            frp = item.get("frp", 0.0) or 0.0

            if lat is None or lon is None or not acq_date:
                continue

            # Extract year from "YYYY-MM-DD"
            year = acq_date.split("-")[0]

            # Determine Hexagon Cell
            q, r, center_lat, center_lon = latlon_to_hex(float(lat), float(lon), HEX_SIZE_DEG)

            # Aggregate
            cell_key = (year, q, r)
            record = hex_data[cell_key]
            record[0] += 1  # fire count / density
            record[1] += float(frp)  # sum of fire radiative power
            record[2] = center_lat  # hexagon centroid latitude
            record[3] = center_lon  # hexagon centroid longitude

    print(f"Aggregation complete! Reduced to {len(hex_data):,} hexagon-year entries.")

    # Write output to CSV
    print(f"Writing compressed dataset to '{OUTPUT_CSV_PATH}'...")
    with open(OUTPUT_CSV_PATH, "w", newline="", encoding="utf-8") as f:
        writer = csv.writer(f)
        writer.writerow(["year", "hex_q", "hex_r", "latitude", "longitude", "fire_count", "total_frp"])

        for (year, q, r), (count, total_frp, c_lat, c_lon) in hex_data.items():
            writer.writerow([year, q, r, c_lat, c_lon, count, round(total_frp, 2)])

    print("Finished successfully!")


if __name__ == "__main__":
    process_large_json()
